            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if (nr,nc) in cells and (nr,nc) not in seen:
                    seen.add((nr,nc)); comp.add((nr,nc)); stack.append((nr,nc))
        main=sorted(comp)[0]
        others=cells-comp
        sr,sc,er,ec=bbox(main)
        for r in range(sr,er+1):
            for c in range(sc,ec+1):
