def solve(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(x for row in inp for x in row)
    bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in inp]
    # 1-pass: build comps over ALL non-bg cells treating each color independently
    cells=defaultdict(set)
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=bg: cells[inp[r][c]].add((r,c))
    def comps(cl):
        seen=set(); res=[]
        for start in sorted(cl):
            if start in seen: continue
            seen.add(start); st=[start]; comp=[]
            while st:
                r,c=st.pop(); comp.append((r,c))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=r+dr,c+dc
                    if (nr,nc) in cl and (nr,nc) not in seen:
                        seen.add((nr,nc)); st.append((nr,nc))
            res.append(comp)
        return res
    keep_cells=set()
    for v,cl in cells.items():
        for comp in comps(cl):
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            sr,sc,er,ec=min(rs),min(cs),max(rs),max(ec)
            holes=any((r,c) not in set(comp) and sr<=r<=er and sc<=c<=ec
                     for r in range(sr,er+1) for c in range(sc,ec+1))
            if holes: keep_cells.update(comp)
            for (r,c) in comp: out[r][c]=v
    # delete everything else
    for r in range(H):
        for c in range(W):
            if out[r][c]!=bg and (r,c) not in keep_cells: out[r][c]=bg
    return out
